// Owner controls use the same visual language, with operational data scoped by shop.
if(state.role==='Owner HQ')state.scope=state.scope||extras.location;
function ownerScopeBookings(){const scope=state.scope||extras.location;return bookings.filter(b=>scope==='all'||(b.location||'scottsdale')===scope);}
function ownerDaySummary(list,date){const active=list.filter(b=>b.date===date&&b.status!=='cancelled'),approved=active.filter(b=>b.ticket?.approval),paid=approved.filter(b=>b.settlement?.status==='paid'&&b.settlement.amountCents===b.ticket.approval.totalCents);return {appointments:active.length,collectedCents:paid.reduce((n,b)=>n+b.settlement.amountCents,0),awaitingApproval:active.filter(b=>b.ticket?.status==='awaiting_approval').length,outstandingCents:approved.filter(b=>!paid.includes(b)).reduce((n,b)=>n+b.ticket.approval.totalCents,0),completed:approved.length};}
function ownerVisitStatus(b){return b.status==='cancelled'?'Cancelled':b.ticket?.approval?b.settlement?.status==='paid'?'Completed · paid':'Approved · unpaid':b.ticket?.status==='awaiting_approval'?'Awaiting approval':checked[b.id]?'In the chair':b.status==='pending_payment'?'Pending prepayment':'Booked';}
function ownerVisitRow(b){const staff=barbers.find(x=>x.id===b.barber);return `<button class="owner-visit-row" data-owner="visit" data-id="${esc(b.id)}"><time>${esc(b.time)}</time>${matchedPortraits(b.client,b.barber)}<span class="owner-visit-person"><strong>${esc(b.client)}</strong><small>${esc(staff?.name||'Barber')} · ${esc(bookingName(b))}</small><span class="owner-visit-status">${ownerVisitStatus(b)}</span></span><span class="owner-visit-amount">${cents(b.ticket?.approval?.totalCents??b.estimateCents??0)}${icon('chevron')}</span></button>`;}
ownerHome=function(){const list=ownerScopeBookings(),summary=ownerDaySummary(list,state.calendarDate),visits=list.filter(b=>b.date===state.calendarDate&&b.status!=='cancelled').sort((a,b)=>minutes(a.time)-minutes(b.time)),scope=state.scope||extras.location;return `${head('Your shop. In focus.',`${scope==='all'?'All stores':shops[scope]?.name} · ${pretty(state.calendarDate)}`)}<section class="owner-summary panel">${[['card','Collected',cents(summary.collectedCents),'Recorded payments · includes tips'],['calendar','Appointments',summary.appointments,'On the selected day'],['clock','Awaiting approval',summary.awaitingApproval,'Client action needed'],['wallet','Outstanding',cents(summary.outstandingCents),'Approved, not recorded as paid']].map(([type,label,value,detail])=>`<div class="owner-metric">${icon(type)}<span>${label}</span><strong>${value}</strong><small>${detail}</small></div>`).join('')}</section><div class="owner-quick-actions"><button class="btn" data-owner="booking">${icon('plus')} Add booking</button><button class="btn secondary" data-view="calendar">${icon('calendar')} Master calendar</button></div><div class="owner-dashboard-grid"><section class="panel owner-day"><div class="owner-section-head"><h2>Daily appointments</h2><button class="text-btn" data-view="calendar">View calendar ${icon('arrow')}</button></div>${visits.length?visits.map(ownerVisitRow).join(''):'<div class="owner-empty"><h3>A clear schedule.</h3><p>No visits recorded for this day and store.</p><button class="text-btn" data-owner="booking">Add the first booking →</button></div>'}</section><section class="panel owner-floor"><div class="owner-section-head"><h2>Your people</h2><button class="text-btn" data-view="team">Manage ${icon('arrow')}</button></div>${barbers.map(staff=>{const own=visits.filter(b=>b.barber===staff.id),s=ownerDaySummary(list.filter(b=>b.barber===staff.id),state.calendarDate),off=dayBlocked(state.calendarDate,staff.id);return `<button class="owner-staff-row" data-owner="staff" data-id="${staff.id}">${photo(staff)}<span><strong>${esc(staff.name)}</strong><small>${own.length} visit${own.length===1?'':'s'} · ${cents(s.collectedCents)} collected</small></span><span class="owner-staff-state ${off?'off':''}">${off?'Day off':own.some(b=>checked[b.id]&&!b.ticket?.approval)?'In the chair':own.length?'On the schedule':'No visits'}</span></button>`;}).join('')}</section><section class="panel owner-week"><div class="owner-section-head"><h2>Collected this week</h2><span class="owner-muted">Includes tips</span></div>${ownerWeekChart(list)}</section><section class="panel owner-shortcuts"><h2>Keep things moving</h2>${[['hMessages','message','Shop inbox'],['hFeedback','star','Private client feedback'],['hPayouts','card','Payment records'],['businessSettings','settings','Booking policies']].map(([page,type,label])=>`<button data-view="${page}">${icon(type)}<span>${label}</span>${icon('chevron')}</button>`).join('')}</section></div>`;};
function ownerWeekChart(list){const days=Array.from({length:7},(_,i)=>addDays(state.calendarDate,i-6)),totals=days.map(date=>ownerDaySummary(list,date).collectedCents),max=Math.max(...totals,1);return `<div class="owner-bars" role="img" aria-label="${days.map((d,i)=>pretty(d)+': '+cents(totals[i])).join('; ')}">${days.map((d,i)=>`<div class="owner-bar-column"><small>${cents(totals[i])}</small><div class="owner-bar-track"><span style="height:${totals[i]?Math.max(4,totals[i]/max*100):0}%"></span></div><small>${pretty(d,{weekday:'short'})}</small></div>`).join('')}</div>`;}
const payoutsBeforeOwner=payoutPage;payoutPage=function(owner){if(!owner||state.role!=='Owner HQ')return payoutsBeforeOwner(owner);const list=ownerScopeBookings().filter(b=>b.ticket?.approval).sort((a,b)=>b.date.localeCompare(a.date)||minutes(b.time)-minutes(a.time));return `${head('Every payment, accounted for.','Approved services and recorded payments.')}<section class="panel owner-payment-note"><h2>Payment records</h2><p>This ledger separates recorded payments from approved amounts. Bank transfers and payout balances are not connected here.</p></section>${list.length?list.map(ownerVisitRow).join(''):'<section class="panel owner-empty"><h2>No approved visits yet.</h2><p>Completed service approvals will appear here.</p></section>'}`;};
const directoryBeforeOwner=directory;directory=function(){if(state.role!=='Owner HQ')return directoryBeforeOwner();return `${head('Your shop, your way.','Manage the people, policies and details.')}<section class="panel owner-manage">${[['hServices','scissors','Services & pricing'],['hCustomers','users','Client directory'],['businessSettings','settings','Booking & chair agreements'],['hLoyalty','gift','Loyalty program'],['hPayouts','card','Payment records'],['hFeedback','star','Private client feedback'],['settings','pin','Shop profile']].map(([page,type,label])=>`<button data-view="${page}">${icon(type)}<span>${label}</span>${icon('chevron')}</button>`).join('')}</section>`;};
const renderBeforeOwner=render;render=function(){renderBeforeOwner();document.body.dataset.owner=state.role==='Owner HQ'?'true':'false';if(state.role!=='Owner HQ')return;
 const top=document.querySelector('.topbar');top?.querySelector('.mobile-brand')?.remove();top?.querySelector('.location')?.remove();top?.insertAdjacentHTML('afterbegin',`<button class="owner-brand" data-view="home" aria-label="Hairflix overview"><span class="owner-pole" aria-hidden="true"></span>HAIRFLIX</button>`);
 const store=top?.querySelector('#shop-location-switch');if(store){store.outerHTML=`<select id="owner-store" aria-label="Filter owner views by store"><option value="all" ${state.scope==='all'?'selected':''}>All stores</option>${Object.entries(shops).map(([id,s])=>`<option value="${id}" ${(state.scope||extras.location)===id?'selected':''}>${s.name}</option>`).join('')}</select>`;}
 top?.querySelector('.store-label')?.remove();top?.querySelector('.account-avatar-button')?.remove();
 if(state.view==='home')document.querySelector('.booking-toolbar')?.remove();
 if(state.view==='calendar'){
 document.querySelector('#calendar-scope')?.closest('label')?.remove();
 const list=ownerScopeBookings().filter(b=>b.date===state.calendarDate&&b.status!=='cancelled').sort((a,b)=>minutes(a.time)-minutes(b.time));
 const panel=document.querySelector('main>.panel');if(panel){panel.classList.add('owner-calendar-visits');panel.innerHTML=list.length?list.map(ownerVisitRow).join(''):'<div class="owner-empty"><h3>No visits recorded.</h3><p>Choose another day or add a booking.</p></div>';}
 }
 const nav=document.querySelector('.bottom-nav');nav?.classList.add('owner-nav');const groups=['staffReceipt','pAppointment','pTicket','pFinalize','manualBooking'].includes(state.view)?'calendar':['hMember','hInvite'].includes(state.view)?'team':state.view==='home'?'home':state.view==='calendar'?'calendar':state.view==='team'?'team':state.view==='hMessages'?'hMessages':'more';
 nav?.querySelectorAll('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===groups);if(el.dataset.view===groups)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
};
document.addEventListener('change',e=>{if(e.target.id!=='owner-store'||state.role!=='Owner HQ')return;state.scope=e.target.value;if(shops[e.target.value]){extras.location=e.target.value;save();}render();});
document.addEventListener('click',e=>{const el=e.target.closest('[data-owner]');if(!el||state.role!=='Owner HQ')return;const d=el.dataset;if(d.owner==='booking'){state.bookingThread=null;go('manualBooking');}if(d.owner==='visit'){rememberAppointmentOrigin();openAppointment(d.id);}if(d.owner==='staff'){state.member=d.id;go('hMember');}});
render();
